/**
 * Replaces an existing result with Fox victory only at the configured final predicate. Inputs
 * are the World and existing faction victory decision; output preserves the appropriate Fox result data. It
 * does not run night inspections or resolve damage during result projection.
 */
import {
  COMPONENT,
  Role,
  Camp,
  type World,
  type WinDecision,
  type RoleComponent,
} from "../../../../core/domain";
import { victoryDecision } from "../../win_conditions/results";
import { CURSED_FOX_GOAL } from "./profile";
export function replaceWithFoxVictory(world: World, decision: WinDecision): WinDecision {
  if (
    decision.outcome.kind !== "victory" ||
    decision.outcome.primary.kind !== "faction" ||
    ![Camp.Good, Camp.Wolf].includes(decision.outcome.primary.faction as Camp)
  )
    return decision;
  const fox = world.getAliveEntityIds().find((id) => {
    const role = world.getComponent(id, COMPONENT.Role);
    return role?.role === Role.CursedFox && role.camp === Camp.ThirdParty;
  });
  return fox === undefined
    ? decision
    : victoryDecision(
        world,
        { kind: "individual", goalId: CURSED_FOX_GOAL, playerId: fox },
        "cursed_fox_survived_faction_elimination",
      );
}

/**
 * 负责 咒狐 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { roleName, text } from "@ai-werewolf-arena/game-text";
import { Camp, Role, WinCondition } from "../../../../core/domain/model";
import type { NativeRoleContributions } from "../contracts";
export const CURSED_FOX_GOAL = "netease_cursed_fox_last_faction_v1";
/** 规则来源与工程补全见 docs/rules/netease-cursed-fox-v1.md。 */
export const CURSED_FOX_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.CursedFox,
    camp: Camp.ThirdParty,
    maxCount: 1,
    label: roleName("cursed_fox"),
    skillBrief: text("zh-CN", "role.cursed_fox.brief"),
    supportedWinConditions: [WinCondition.SlaughterCity],
    supportedBoardRoles: [
      Role.CursedFox,
      Role.Wolf,
      Role.WolfKing,
      Role.WhiteWolfKing,
      Role.HiddenWolf,
      Role.Seer,
      Role.Witch,
      Role.Guard,
      Role.Hunter,
      Role.Idiot,
      Role.Villager,
      Role.Knight,
      Role.Dreamer,
      Role.MiracleMerchant,
      Role.MirrorGirl,
    ],
  },
  runtime: {
    initialVictoryAffiliations: [{ kind: "individual", goalId: CURSED_FOX_GOAL }],
    inspectionLabels: { camp: Camp.Good },
    configuration: {
      schema: z.strictObject({}),
      defaults: {},
      apply: (config) => config,
      serialize: () => ({}),
    },
  },
  presentation: nativeRolePresentation("cursed_fox"),
};

/**
 * 负责鬼魂新娘婚礼回合、原参与者快照与有序提交，拥有婚礼选择和绑定别名的写权。
 * 输入保留原 World 及封存请求；输出为原校验后已接受的选择、消息与结算记录。
 * 不变量：提交必须匹配原参与者和绑定回合，别名不能替代本地校验。取消、关闭或失败
 * 均保持原结算及部分写入顺序，不修复被替换的库存。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import type { WeddingActorView } from "@ai-werewolf-arena/game-contract/facts/ghost-bride";
import { registerRequestAliasPropagation } from "../../../../core/domain/request_delivery";
import { types } from "node:util";
import { GHOST_BRIDE_POLICY, GHOST_BRIDE_ROLE, freshGhostBrideState, readGhostBrideState, type GhostBrideState, type WeddingPair, type WeddingGroup, type WeddingSetup, type WeddingKnifeCapture, type WeddingTool, readWeddingTool } from "@ai-werewolf-arena/game-contract/facts/ghost-bride";
import {
  bindRequestDeliveryGuard,
  settleRequestDelivery,
  DeathCause,
  type DeathSources,
  COMPONENT,
  Camp,
  Role,
  Phase,
  createVictoryComponent,
  type World,
  type RoleComponent,
  type CampComponent,
  type VictoryComponent,
} from "../../../../core/domain";
import {
  aliveLifeVersion,
  aliveLifeDescriptor,
  type AliveComponent,
} from "../../../../core/domain/components/alive";
import { assertGhostBridePreset } from "./preset";

/** 只读 own data；拒绝或审计期间不执行被替换的 getter。 */
function data(value: unknown, key: string): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && Object.hasOwn(d, "value") ? d.value : undefined;
}
function snapshot(value: unknown, depth = 0, arrayLimit = 128): unknown {
  if (
    value === null ||
    ["string", "boolean"].includes(typeof value) ||
    (typeof value === "number" && Number.isFinite(value))
  )
    return value;
  if (
    !value ||
    typeof value !== "object" ||
    types.isProxy(value) ||
    depth > 12 ||
    Object.getOwnPropertySymbols(value).length
  )
    throw new Error("ghost_bride_authority_not_data");
  const array = Array.isArray(value),
    proto = Object.getPrototypeOf(value);
  if (array ? proto !== Array.prototype : proto !== Object.prototype && proto !== null)
    throw new Error("ghost_bride_authority_not_plain");
  const fields = Object.getOwnPropertyDescriptors(value),
    result: Record<string, unknown> = {};
  for (const [key, d] of Object.entries(fields)) {
    if (array && key === "length") continue;
    if (!d.enumerable || !Object.hasOwn(d, "value"))
      throw new Error("ghost_bride_authority_accessor");
    Object.defineProperty(result, key, {
      value: snapshot(d.value, depth + 1, arrayLimit),
      enumerable: true,
    });
  }
  if (!array) return result;
  const length = fields.length?.value;
  if (
    !Number.isSafeInteger(length) ||
    length > arrayLimit ||
    Object.keys(result).length !== length ||
    !Array.from({ length }, (_, i) => Object.hasOwn(result, i)).every(Boolean)
  )
    throw new Error("ghost_bride_authority_array");
  return Array.from({ length }, (_, i) => result[i]);
}
function json(value: unknown): string | null {
  try {
    return JSON.stringify(snapshot(value));
  } catch {
    return null;
  }
}
interface Participant {
  id: number;
  role: RoleComponent;
  kind: Role;
  camp: Camp;
  campComponent: CampComponent;
  state: RoleComponent["privateState"];
  stateRefs: ReadonlyArray<readonly [string, unknown]>;
  initialPrivateState: unknown;
  expectedPrivateJson: string;
  auditPrivateJson: string;
  life: AliveComponent;
  version: number;
  aliveDescriptor: PropertyDescriptor;
  victory: VictoryComponent;
  affiliations: VictoryComponent["affiliations"];
  victoryJson: string;
}
type TurnKind = "bridegroom" | "chat" | "witness" | "knife";
interface Binding {
