        (n.capture.owner === "pair" && [b.actorId, b.pair!.groomId].includes(id)) ||
        (n.capture.owner === "witness" && id === t.actorId))
    )
      return false;
    n.votes.push(Object.freeze({ actorId: t.actorId, targetId: id, abstain: call.args.abstain }));
  }
  if (t.kind !== "chat") settleRequestDelivery(scope, true);
  closeWeddingTurn(scope);
  return true;
}
function validKnifeOwner(n: Night): boolean {
  const b = n.binding;
  return (
    b.activeNight === n &&
    !n.closed &&
    n.isCurrent() &&
    b.status === "complete" &&
    validBinding(b) &&
    n.capture.actorIds.every((id) => {
      const p = b.participants.get(id)!;
      return sameBody(b, p, true) && aliveLifeVersion(p.life) === n.actorVersions.get(id);
    })
  );
}
export function captureWeddingKnife(
  world: World,
  day: number,
  isCurrent: () => boolean,
): Readonly<WeddingKnifeCapture> {
  const b = bindings.get(world);
  if (
    !b ||
    b.status !== "complete" ||
    !b.group ||
    b.activeNight ||
    b.nights.has(day) ||
    !Number.isSafeInteger(day) ||
    day < 1 ||
    !isCurrent() ||
    !validBinding(b)
  )
    throw new Error("ghost_bride_night_unavailable");
  const groupIds = [b.actorId, b.group.groomId, b.group.witnessId],
    singles = [...b.participants.values()]
      .filter((p) => p.kind === Role.Wolf && !groupIds.includes(p.id) && sameBody(b, p, true))
      .map((p) => p.id),
    pairIds = [b.actorId, b.group.groomId],
    pairAlive = pairIds.every((id) => sameBody(b, b.participants.get(id)!, true)),
    pairDead = pairIds.every((id) => !b.participants.get(id)!.life.alive),
    witnessAlive = sameBody(b, b.participants.get(b.group.witnessId)!, true);
  const owner = singles.length
      ? "ordinary_pack"
      : pairAlive
        ? "pair"
        : pairDead && witnessAlive
          ? "witness"
          : "none",
    actorIds = singles.length
      ? singles
      : owner === "pair"
        ? pairIds
        : owner === "witness"
          ? [b.group.witnessId]
          : [];
  const capture = Object.freeze({
    policy: GHOST_BRIDE_POLICY,
    groupId: b.group.groupId,
    day,
    owner,
    actorIds: Object.freeze(actorIds) as unknown as number[],
  });
  const n: Night = {
    binding: b,
    day,
    capture,
    isCurrent,
    actorVersions: new Map(
      actorIds.map((id) => [id, aliveLifeVersion(b.participants.get(id)!.life)!]),
    ),
    targetVersions: new Map([...b.participants].map(([id, p]) => [id, aliveLifeVersion(p.life)!])),
    votes: [],
    chats: 0,
    requiredChats: day > 1 && pairAlive ? 2 : 0,
    closed: false,
    knifeCommitted: false,
    targetId: null,
  };
  b.nights.set(day, n);
  b.activeNight = n;
  return capture;
}
export function resolveWeddingKnife(world: World, day: number): number | null {
  const n = bindings.get(world)?.activeNight;
  if (!n || n.day !== day || n.knifeCommitted) throw new Error("ghost_bride_knife_unavailable");
  n.knifeCommitted = true;
  if (!validKnifeOwner(n)) {
    n.targetId = null;
    return null;
  }
  if (n.votes.length !== n.capture.actorIds.length || n.chats !== n.requiredChats)
    throw new Error("ghost_bride_required_knife_missing");
  const counts = new Map<number, number>();
  for (const v of n.votes)
    if (!v.abstain && v.targetId !== null)
      counts.set(v.targetId, (counts.get(v.targetId) ?? 0) + 1);
  const target = [...counts].sort((a, b) => b[1] - a[1] || a[0] - b[0])[0]?.[0] ?? null;
  const p = target === null ? undefined : n.binding.participants.get(target);
  n.targetId =
    p && sameBody(n.binding, p, true) && aliveLifeVersion(p.life) === n.targetVersions.get(p.id)
      ? p.id
      : null;
  return n.targetId;
}
export function weddingKnifeCurrent(world: World, day: number, targetId: number): boolean {
  const n = bindings.get(world)?.activeNight,
    p = n?.binding.participants.get(targetId);
  return (
    !!n &&
    n.day === day &&
    n.knifeCommitted &&
    n.targetId === targetId &&
    validKnifeOwner(n) &&
    !!p &&
    sameBody(n.binding, p, true) &&
    aliveLifeVersion(p.life) === n.targetVersions.get(targetId)
  );
}
export function closeWeddingNight(world: World): void {
  const b = bindings.get(world);
  if (!b?.activeNight) return;
  if (b.turn) settleRequestDelivery(b.turn.scope, false);
  if (b.pendingChat) settleRequestDelivery(b.pendingChat.scope, false);
  b.activeNight.closed = true;
  b.activeNight = null;
  b.turn = null;
  b.pendingChat = null;
}
export function weddingMember(world: World, role: RoleComponent): boolean {
  const b = bindings.get(world);
  if (!b?.pair) return false;
  if (!validBinding(b)) throw new Error("ghost_bride_authority_invalid");
  return [b.actorId, b.pair.groomId, b.group?.witnessId].some(
    (id) => id !== undefined && b.participants.get(id)?.role === role,
  );
}
export function weddingAssignment(world: World): ReadonlyArray<readonly [number, Camp]> | null {
  const b = bindings.get(world);
  if (!b) return null;
  if (b.status !== "complete" || !b.assignments || !validBinding(b))
    throw new Error("ghost_bride_victory_unavailable");
  return Object.freeze([...b.assignments].map(([id, camp]) => Object.freeze([id, camp] as const)));
}
export function weddingFactionResult(
  world: World,
): { faction: Camp | null; winningPlayerIds: number[] } | null {
  const b = bindings.get(world),
    assignment = weddingAssignment(world);
  if (!b || !assignment) return null;
  const alive = new Set(
    assignment.filter(([id]) => sameBody(b, b.participants.get(id)!, true)).map(([, camp]) => camp),
  );
  if (alive.size > 1) return null;
  const faction = [...alive][0] ?? null;
  return {
    faction,
    winningPlayerIds: faction
      ? assignment.filter(([, camp]) => camp === faction).map(([id]) => id)
      : [],
  };
}
export function weddingAuditPlayer(world: World, id: number, failedCycle = false) {
  const b = bindings.get(world),
    p = b?.participants.get(id);
  if (!b || !p || (!failedCycle && b.status !== "failed" && b.status !== "cancelled")) return null;
  // 分别刷新仍归原 owner 的 plain 库存；其他参与者可能已经失败。
  // json 仅读 descriptor，foreign getter／Proxy 因而保留最近安全快照。
  if (sameBody(b, p) && sameIdentity(b, p)) {
    const encoded = json(p.state);
    if (encoded !== null) p.auditPrivateJson = encoded;
  }
  const alive = p.aliveDescriptor.get
    ? p.aliveDescriptor.get.call(p.life) === true
    : p.aliveDescriptor.value === true;
  return {
    role: p.kind,
    camp: p.camp,
    alive,
    privateState:
      id === b.actorId
        ? {
            ghostBride: {
              ...freshGhostBrideState(),
              remaining: 0,
              groomId: b.pair?.groomId ?? null,
            },
          }
        : (JSON.parse(p.auditPrivateJson) as Record<string, unknown>),
    victory: JSON.parse(p.victoryJson) as VictoryComponent["affiliations"],
  };
}

const deathEdges = new WeakMap<World, Set<string>>();
/** 原生枪资格检查前关闭独立 roots；派生情侣关系不建立反向边。 */
export function expandWeddingDeaths(
  world: World,
  ids: number[],
  sources: DeathSources,
  eligibleDead: ReadonlySet<number>,
  nightOrigin?: Set<number>,
): Array<{ actorId: number; targetId: number }> {
  const b = bindings.get(world);
  if (!b) return [];
  if (b.status !== "complete" || !b.group || !validBinding(b))
    throw new Error("ghost_bride_relation_unavailable");
  const pairIds = [b.actorId, b.group.groomId],
    members = new Set(ids),
    roots = new Set(ids.filter((id) => (sources[id] ?? []).some((c) => c !== DeathCause.Lovers))),
    edges: Array<{ actorId: number; targetId: number }> = [],
    emitted = deathEdges.get(world) ?? new Set<string>();
  for (const root of pairIds) {
    if (!roots.has(root)) continue;
    const target = pairIds.find((id) => id !== root)!,
      p = b.participants.get(target)!;
    if (!sameBody(b, p, true) && !members.has(target) && !eligibleDead.has(target)) continue;
    if (!members.has(target)) {
      members.add(target);
      ids.push(target);
    }
    if (!(sources[target] ?? []).includes(DeathCause.Lovers))
      sources[target] = [...(sources[target] ?? []), DeathCause.Lovers];
    if (nightOrigin?.has(root)) nightOrigin.add(target);
    const key = `${root}:${target}`;
    if (!emitted.has(key)) {
      emitted.add(key);
      edges.push({ actorId: root, targetId: target });
    }
  }
  deathEdges.set(world, emitted);
  return edges;
}

export function weddingNightCapture(
  world: World,
  day: number,
): Readonly<WeddingKnifeCapture> | null {
  return bindings.get(world)?.nights.get(day)?.capture ?? null;
}

/** 重检双方原生命及原请求后，仅消耗一次已提交消息。 */
export function takeWeddingChat(
  scope: object,
): { actorId: number; recipientId: number; day: number; text: string } | null {
  const t = turns.get(scope),
    message = t?.chat;
  if (!t || !message || t.delivered) return null;
  const b = t.binding,
    setup = b.status !== "complete";
  if (
    b.pendingChat !== t ||
    !t.isCurrent() ||
    (setup && b.setupCurrent?.() !== true) ||
    !validBinding(b, setup) ||
    !validRequestProof(t) ||
    !targetCurrent(t, message.actorId) ||
    !targetCurrent(t, message.recipientId) ||
    (!setup && (!b.activeNight || b.activeNight.day !== t.day || b.activeNight.closed)) ||
    [...b.participants].some(([id, p]) => json(p.state) !== t.privateJson.get(id))
  ) {
    if (b.pendingChat === t) settleRequestDelivery(scope, false);
    return null;
  }
  t.delivered = true;
  b.pendingChat = null;
  if (setup) b.chats++;
  else b.activeNight!.chats++;
  settleRequestDelivery(scope, true);
  return { ...message };
}
/** 与原身份无关的最小关系投影；先复验绑定，canKnife 仍只是此时知识，见证人不接收聊天、票型或原生库存。 */
export function weddingActorView(world: World, actorId: number): WeddingActorView | null {
  const b = bindings.get(world);
  if (!b?.pair || b.status === "failed" || b.status === "cancelled") return null;
  if (!validBinding(b)) throw new Error("ghost_bride_authority_invalid");
  const n = b.activeNight,
    canKnife = !!n && n.capture.actorIds.includes(actorId) && validKnifeOwner(n);
  if (actorId === b.actorId || actorId === b.pair.groomId)
    return {
      policy: GHOST_BRIDE_POLICY,
      member: actorId === b.actorId ? "bride" : "groom",
      faction: Camp.ThirdParty,
      partnerId: actorId === b.actorId ? b.pair.groomId : b.actorId,
      witnessId: b.group?.witnessId ?? null,
      ...(actorId === b.pair.groomId && b.votes.length === 1
        ? { proposedWitnessId: b.votes[0]!.targetId }
        : {}),
      canKnife,
    };
  return actorId === b.group?.witnessId
    ? {
        policy: GHOST_BRIDE_POLICY,
        member: "witness",
        faction: Camp.ThirdParty,
        brideId: b.actorId,
        groomId: b.pair.groomId,
        canKnife,
      }
    : null;
}

/** 纯 preflight 与提交使用同一原体／请求目标证明。 */
export function canSubmitWeddingTool(
  world: World,
  actorId: number,
  phase: Phase,
  day: number,
  scope: object | undefined,
  value: unknown,
): boolean {
  const t = scope && turns.get(scope),
    call = readWeddingTool(value);
  if (
    !t ||
    !call ||
    call.name !== t.tool ||
    !authorizedWeddingTurn(world, actorId, phase, day, scope)
  )
    return false;
  if (call.name === "speak_to_partner")
    return targetCurrent(
      t,
      t.actorId === t.binding.actorId ? t.binding.pair!.groomId : t.binding.actorId,
    );
  const id = call.args.target_id;
  if (id === null) return call.name === "kill_vote" || call.name === "wedding_kill_vote";
  if (!targetCurrent(t, id)) return false;
  if (call.name === "choose_bridegroom") return id !== t.binding.actorId;
  if (call.name === "choose_wedding_witness")
    return id !== t.binding.actorId && id !== t.binding.pair!.groomId;
  const owner = t.binding.activeNight!.capture.owner;
  return owner === "pair"
    ? ![t.binding.actorId, t.binding.pair!.groomId].includes(id)
    : owner !== "witness" || id !== actorId;
}
export function weddingBrideState(world: World, actorId: number): GhostBrideState | null {
  const b = bindings.get(world);
  if (!b || actorId !== b.actorId) return null;
  if (!validBinding(b)) throw new Error("ghost_bride_authority_invalid");
  return readGhostBrideState(b.state);
}

const swallowedBadges = new WeakSet<World>();
export function weddingBadgeSwallowed(world: World): boolean {
  return swallowedBadges.has(world);
}
export function swallowWeddingBadges(
  world: World,
  events: import("../../../../core/domain").GameEvent[],
): void {
  const b = bindings.get(world);
  if (!b || !ghostBrideReady(world)) throw new Error("ghost_bride_badge_authority_invalid");
  swallowedBadges.add(world);
  for (const id of world.entityIds()) {
    const badge = world.getComponent(id, COMPONENT.Badge);
    const vote = world.getComponent(id, COMPONENT.VotingRight);
    if (badge) {
      if (badge.isSheriff && !badge.destroyed)
        events.push({
          timestamp: Date.now(),
          type: "sheriff_badge_destroyed",
          payload: { targetId: id, reason: "ghost_bride_single_wolf_blast" },
        });
      badge.isSheriff = false;
      badge.destroyed = true;
      badge.voteWeight = 1;
      delete badge.handoffPolicy;
    }
    if (vote) vote.weight = vote.canVote ? 1 : 0;
  }
}

/**
 * 负责终局候选的完整结构、胜利成员和决定时点校验，输入为候选与当前世界／日期的晚读端口。
 * 输出为已核对的 winner、outcome 和 decidedAt 数据；不选择胜负规则、不写入终局或发布事件。
 * 成员按独立 Victory 归属重建，不由角色或实际阵营猜测；单人、关系及附加胜利保原顺序。
 * 结构拒绝、赢家／理由拒绝、成员拒绝、时点拒绝依次发生；调用方仍拥有必要死亡链及唯一封盘。
 */
import type {
  Camp,
  GameOutcome,
  Phase,
  VictoryCheckpoint,
  VictoryPoint,
  WinDecision,
} from "@ai-werewolf-arena/game-contract";
import type { World } from "../../../core/domain/world";
import { readGameOutcome, readVictoryPoint } from "@ai-werewolf-arena/replay-contract";
import { victoryDecision } from "./results";

/** 校验结果尚未封盘；它不携带资源／行动权限，也不替代引擎的当前终态检查。 */
export interface ValidatedVictoryDecision {
  readonly winner: Camp | null;
  readonly outcome: GameOutcome;
  readonly decidedAt: VictoryPoint;
}

export function validateVictoryDecision(
  decision: WinDecision,
  checkpoint: VictoryCheckpoint,
  phase: Phase,
  world: () => World,
  day: () => number,
): ValidatedVictoryDecision {
  const outcome = readGameOutcome(decision.outcome, world().entityIds());
  const winner =
    outcome.kind === "victory" && outcome.primary.kind === "faction"
      ? (outcome.primary.faction as Camp)
      : null;
  if (
    winner !== decision.winner ||
    typeof decision.reason !== "string" ||
    decision.reason.length === 0
  )
    throw new Error("game_result_invalid");
  if (outcome.kind === "victory") {
    const targets = [outcome.primary, ...outcome.additional].map(
      ({ winningPlayerIds: _ids, ...target }) => target,
    );
    const expected = victoryDecision(
      world(),
      targets[0],
      decision.reason,
      targets.slice(1),
    ).outcome;
    if (JSON.stringify(expected) !== JSON.stringify(outcome))
      throw new Error("game_result_membership_invalid");
  }
  // 日期只在所有成员检查通过后读取，校验失败不提前观察或改写阶段状态。
  const decidedAt = readVictoryPoint({ day: day(), phase, checkpoint });
  return { winner, outcome, decidedAt };
}

/**
 * 负责把已接受的胜利判定投影成结构化结果。输入为当前胜利归属、已判目标与原因，输出保留获胜成员和 claim 数据。
 * 本模块不重新选择屠边政策、不修改玩家组件；判胜仍由原胜利条件与检查点负责。
 */
import type { GameOutcome, VictoryClaim, VictoryTarget } from "@ai-werewolf-arena/game-contract";
import { COMPONENT, type WinDecision, type World } from "../../../core/domain";
import type { VictoryComponent } from "../../../core/domain/components/victory";
import { readGameOutcome } from "@ai-werewolf-arena/replay-contract";

/** 成员来自明确 Victory 组件，不根据角色或真实阵营推断。 */
export function victoryDecision(
  world: World,
  primary: VictoryTarget,
  reason: string,
  additional: readonly VictoryTarget[] = [],
): WinDecision {
  const claim = (target: VictoryTarget): VictoryClaim => {
    const winningPlayerIds = world.entityIds().filter((id) => {
      if (target.kind === "individual" && id !== target.playerId) return false;
      return (
        world
          .getComponent(id, COMPONENT.Victory)
          ?.affiliations.some(
            (member) =>
              (target.kind === "faction" &&
                member.kind === "faction" &&
                target.faction === member.faction) ||
              (target.kind === "individual" &&
                member.kind === "individual" &&
                target.goalId === member.goalId) ||
              (target.kind === "relationship" &&
                member.kind === "relationship" &&
                target.groupId === member.groupId),
          ) === true
      );
    });
    if (target.kind !== "faction" && winningPlayerIds.length === 0)
      throw new Error("victory_target_has_no_members");
    return { ...target, winningPlayerIds };
  };
  const first = claim(primary),
    others = additional.map(claim);
  const outcome: GameOutcome = {
    kind: "victory",
    primary: first,
    additional: others,
    winningPlayerIds: [
      ...new Set([first, ...others].flatMap((item) => item.winningPlayerIds)),
    ].sort((a, b) => a - b),
  };
  if (typeof reason !== "string" || reason.length === 0) throw new Error("victory_reason_invalid");
  return {
    winner: primary.kind === "faction" ? (primary.faction as WinDecision["winner"]) : null,
    reason,
    outcome: readGameOutcome(outcome, world.entityIds()),
  };
}

/**
 * 负责胜利条件的有序委托与覆盖结果优先选择。输入为原 World、只读条件 ID、检查点及覆盖数据；输出为首个原判定或 null。
 * 本入口不改变参数数组或封存结果，真实检查点执行与终局仍由 PhaseManager 持有。
 */
import type { VictoryCheckpoint } from "@ai-werewolf-arena/game-contract";
import { WinDecision, WinCondition } from "../model";
import { World } from "../world";

/**
 * 胜负判定注册中心抽象：由机制层实现并在装配期注入。
 */
export interface WinConditionEvaluator {
  evaluate(
    world: World,
    condition: WinCondition,
    checkpoint?: VictoryCheckpoint,
  ): WinDecision | null;
}

/**
 * 胜负条件入口：委托机制层 WinConditionRegistry。
 */
export class ConditionRegistry {
  private readonly winRegistry: WinConditionEvaluator;

  constructor(winRegistry: WinConditionEvaluator) {
    this.winRegistry = winRegistry;
  }

  /**
   * 按指定胜负模式执行胜负判定。
   */
  evaluate(
    world: World,
    condition: WinCondition,
    checkpoint?: VictoryCheckpoint,
  ): WinDecision | null {
    return this.winRegistry.evaluate(world, condition, checkpoint);
  }

  /**
   * 按给定顺序评估多个胜负模式，命中即返回。
   */
  evaluateMany(
    world: World,
    conditions: readonly WinCondition[],
    checkpoint?: VictoryCheckpoint,
    overrides: Partial<Record<WinCondition, WinDecision>> = {},
  ): WinDecision | null {
    for (const condition of conditions) {
      const result = overrides[condition] ?? this.evaluate(world, condition, checkpoint);
      if (result) {
        return result;
      }
    }
    return null;
  }
}

/**
 * 负责：拥有一次真实执行的规则计划及唯一 BoardParameters 引用。
 * 输入：已绑定参数、原时点采集的阶段贡献和延迟读取的夜间运行端口；
 * 输出：实际引擎使用的原 handler、原生策略、生命周期单位及脱离运行态的归档参数。
 * 默认自有数据贡献在首次晚收集时固定成员与顺序，后续变化明确拒绝隐式 revision。
 * 注入或不透明来源保留原 collector 和惰性拉取；不缓存 execute 函数、角色资格、
 * 玩家、目标、库存或 World，不新增 World 全局表或归档字段。
 */
import { assertCycleAdmission, assertPhaseJumpAdmission } from "./cycle-admission";
import { refreshWolfKnifeInheritanceAtCheckpoint } from "./wolf-knife-inheritance-plan";
import type { BoardParameters } from "./board-parameters";
import type { NightStageRegistry } from "./night-stage-plan";
import type { NightStagePlan, SupportedNightDefinition } from "./night-stage-plan-contracts";
import type { World } from "../core/domain/world";
import { types } from "node:util";
import { bindNativeNightFailurePolicy } from "./native-night-failure-policy";
import { bindNativeNightTargetPolicy } from "./native-night-target-policy";
import { bindNativeNightEffects } from "./native-night-effects";
import {
  NightManagerLifecycle,
  prepareNightPipelineLifecycle,
  type NightManagerLifecycleRuntime,
  type NightPipelineLifecycleRuntime,
  type NightLifecycleHandoff,
} from "./night-lifecycle-plan";

const constructionToken = Symbol("rule-plan-construction");
const checkpoints = Object.freeze({
  nightSettled: "night_settled",
  dayInterrupted: "day_interrupted",
  exileSettled: "exile_settled",
  maxDays: "max_days_reached",
} as const);

// 比较贡献序列和原 handler 身份，不读取或缓存 execute；角色实例仍在现场查询。
function sameDefinition(left: SupportedNightDefinition, right: SupportedNightDefinition): boolean {
  if (left.roles.length !== right.roles.length) return false;
  return left.roles.every((row, index) => {
    const other = right.roles[index]!;
    return row.role === other.role &&
      row.handlers.length === other.handlers.length &&
      row.handlers.every((handler, ordinal) => handler === other.handlers[ordinal]) &&
      row.night.length === other.night.length &&
      row.night.every((kind, ordinal) => kind === other.night[ordinal]) &&
      row.death.length === other.death.length &&
      row.death.every((kind, ordinal) => kind === other.death[ordinal]);
  });
}

/** 组合直接复用已存在的具体策略及单位，不另建执行框架。 */
export class RulePlan {
  readonly parameters: BoardParameters;
  readonly nativeNightFailure = bindNativeNightFailurePolicy;
  readonly nativeNightTargets = bindNativeNightTargetPolicy;
  readonly nativeNightEffects = bindNativeNightEffects;
  readonly checkpoints = checkpoints;
  /** 固定同步政策函数；不固定现场状态，每次准入沿调用方 getter 读取原查询点。 */
  readonly cycleAdmission = assertCycleAdmission;
  readonly phaseJumpAdmission = assertPhaseJumpAdmission;
  /** 同步继承贡献不持执行态，经理只在原初始检查点调用。 */
  readonly wolfKnifeInheritance = refreshWolfKnifeInheritanceAtCheckpoint;
  // 只在首次默认晚收集后固定有限贡献；actor、实例和资源始终由现场查询决定。
  #definition: SupportedNightDefinition | null = null;
  // 潜在阶段描述可保留未激活预约，实际 entries 仍使用原 collector 当夜选择。
  #metadata: NightStagePlan["metadata"] | null = null;
  // 记录已固定的标准来源身份；其转为 Proxy/访问器不能绕过 revision 检查。
  #standardRegistry: NightStageRegistry | null = null;

  private constructor(token: typeof constructionToken, parameters: BoardParameters) {
    if (token !== constructionToken) throw new Error("rule_plan_constructor_forbidden");
    this.parameters = parameters;
    Object.freeze(this);
  }

  /** 仅绑定同一参数 owner；不查询 World／registry，默认自有贡献在第一次 nightPlan 的原晚时点固定。 */
  static compile(parameters: BoardParameters): RulePlan {
    return new RulePlan(constructionToken, parameters);
  }

  /** 私有字段品牌先拒绝伪造别名；不执行调用方 getter 或 Proxy trap。 */
  static isOwned(input: unknown): input is RulePlan {
    return input !== null && typeof input === "object" && #definition in input;
  }

  createNightManagerLifecycle(runtime: NightManagerLifecycleRuntime): NightManagerLifecycle {
    return new NightManagerLifecycle(runtime);
  }

  prepareNightPipelineLifecycle(
    runtime: NightPipelineLifecycleRuntime,
    config: Parameters<typeof prepareNightPipelineLifecycle>[1],
    day: number,
    handoff?: () => NightLifecycleHandoff | undefined,
  ) {
    return prepareNightPipelineLifecycle(runtime, config, day, handoff, this.parameters);
  }

  /** 在原时点采集；不透明 iterator 不预先耗尽，下一项仍在前一 handler 提交后拉取。 */
  nightPlan(registry: NightStageRegistry, world: () => World): NightStagePlan {
    // 原调用先读取 getPlan 方法，再求值 World 参数；不能在跨 owner 时倒置 getter 前缀。
    const plan = registry.getPlan(this.parameters.board, world());
    if (plan.mode !== "snapshot") {
      if (registry === this.#standardRegistry)
        throw new Error("rule_plan_revision_not_supported");
      return plan;
    }
    if (plan.definition === null) {
      if (plan.definitionScope === "built-in" && this.#definition !== null)
        throw new Error("rule_plan_revision_not_supported");
      return plan;
    }
    if (this.#definition === null) {
      this.#definition = plan.definition;
      this.#standardRegistry = registry;
      const reserved = plan.definition.reservations.map((handler, ordinal) => {
        if (types.isProxy(handler)) return null;
        const id = Object.getOwnPropertyDescriptor(handler, "id"),
          priority = Object.getOwnPropertyDescriptor(handler, "priority");
        if (!id || !("value" in id) || typeof id.value !== "string" ||
          !priority || !("value" in priority) || typeof priority.value !== "number") return null;
        return Object.freeze({ kind: "data" as const, id: id.value, priority: priority.value, ordinal });
      });
      this.#metadata = Object.freeze([...plan.metadata, ...reserved.filter((entry) => entry !== null)]);
      return plan;
    }
    if (!sameDefinition(this.#definition, plan.definition))
      throw new Error("rule_plan_revision_not_supported");
    // 原体退役后，现场选择可以移除可选预约；固定定义只校验既有 ID/priority，
    // 不把潜在预约插入执行列表，避免多出原事件、record 或 RNG 操作。
    for (const item of plan.metadata) {
      if (item.kind !== "data") throw new Error("rule_plan_revision_not_supported");
      const previous = this.#metadata!.find((entry) => entry.kind === "data" && entry.id === item.id);
      if (!previous || previous.kind !== "data" || previous.priority !== item.priority)
        throw new Error("rule_plan_revision_not_supported");
    }
    return plan;
  }

  /** 归档只编码同一参数 owner 的脱离克隆，计划对象和 callback 不写入归档。 */
  encodeParameters() {
    return this.parameters.encode();
  }
}
Object.freeze(RulePlan.prototype);
Object.freeze(RulePlan);
